    </div>
  </AppLayout>
</template>

<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref } from "vue";import { AlertCircle,ArrowRight,Bot,Check,CheckCircle2,Clock3,Eye,FolderGit2,GitBranch,ImagePlus,LoaderCircle,MessageSquareText,Plus,Send,ShieldCheck,Wand2,X } from "lucide-vue-next";import AppLayout from "../layouts/AppLayout.vue";import BaseModal from "../components/BaseModal.vue";import RegistrySection from "../components/RegistrySection.vue";import ChipField from "../components/ChipField.vue";import GuideField from "../components/GuideField.vue";import FilePicker from "../components/FilePicker.vue";import ItemEditor from "../components/ItemEditor.vue";import MetricEditor from "../components/MetricEditor.vue";import RepoTree from "../components/RepoTree.vue";import SkillTree from "../components/SkillTree.vue";import { useAuthStore } from "../stores/auth";import { apiFetch,readApiError } from "../api/client";
const auth=useAuthStore();const steps=[{title:"자산 명세서 작성",short:"핵심 정보 작성"},{title:"자산 연동",short:"Git 저장소 연결"},{title:"확산 패키지 생성",short:"Claude Skill 생성"},{title:"최종 제출 및 승인",short:"검토 요청 제출"}];const businessAreas=["생산·제조","품질","R&D·설계","SCM·구매·물류","영업·마케팅","경영지원","안전·환경·보건","IT·DX","공통"],maturityLevels=["아이디어","PoC","Pilot","운영"],taskTypes=["예측","탐지","분류","검색","질의응답","요약","생성","추출","추천","분석","최적화","자동화"],implementationTypes=["ML","DL","Computer Vision","LLM","RAG","Agent","Rule-Based","Hybrid"],dataTypes=["테이블·정형데이터","시계열 데이터","센서·IoT 데이터","문서·텍스트","이미지","영상","음성","로그","CAD·도면","코드","웹·외부 데이터","복합 데이터"];
const newTech=()=>({model_name:"",stack_name:"",description:"",reference_url:""}),newComparison=()=>({metric_name:"",before_value:"",after_value:"",improvement_rate:""}),newKpi=()=>({metric_name:"",value:"",description:""}),newSlide=()=>({id:crypto.randomUUID(),file:null,preview:"",caption:"",description:""});const initialForm=()=>({asset_id:crypto.randomUUID(),owner_name:auth.user?.displayed_name||"",owner_job_title:auth.user?.job_title||"",owner_org:auth.user?.org_name||"",owner_email:auth.user?.email||"",asset_name:"",description:"",business_area:"",maturity_level:"",task_types:[],implementation_types:[],tags:[],problem_definition:"",as_is_workflow:"",to_be_workflow:"",ai_effect:"",has_data:true,has_train_validation_split:false,data_type:"",data_description:"",models:[newTech()],tech_stacks:[newTech()],before_after_metrics:[newComparison()],performance_metrics:[newKpi()],repo_url:"",repo_branch:"main"});
const form=reactive(initialForm()),files=reactive({sample:null,train:null,validation:null}),slides=ref([newSlide()]),tagInput=ref(""),step=ref(0),maxStep=ref(0),saving=ref(false),error=ref(""),repoTree=ref([]),cloning=ref(false),repoError=ref(""),skillPlan=ref(null),planning=ref(false),selectedSkills=ref([]),generating=ref(false),generationLabel=ref(""),generatedFiles=ref([]),skillError=ref(""),selectedFile=ref(""),submitted=ref(false),myAssets=ref([]),historyLoading=ref(true),documentHtml=ref(""),feedback=ref(null),slideInput=ref(null),slideTarget=ref(0),agreements=reactive({share:false,factual:false,security:false});
