const filled=value=>String(value||"").trim().length>0,itemsComplete=(items,keys)=>items.length>0&&items.every(item=>keys.every(key=>filled(item[key])));const sectionComplete=computed(()=>({owner:[form.owner_name,form.owner_job_title,form.owner_org,form.owner_email].every(filled),basic:[form.asset_name,form.description,form.business_area,form.maturity_level].every(filled)&&form.task_types.length&&form.implementation_types.length&&form.tags.length,definition:[form.problem_definition,form.as_is_workflow,form.to_be_workflow,form.ai_effect].every(filled),data:!form.has_data||([form.data_type,form.data_description].every(filled)&&(form.has_train_validation_split?(files.train&&files.validation):files.sample)),tech:itemsComplete(form.models,["model_name","description"])&&itemsComplete(form.tech_stacks,["stack_name","description"])&&itemsComplete(form.before_after_metrics,["metric_name","before_value","after_value","improvement_rate"])&&itemsComplete(form.performance_metrics,["metric_name","value","description"]),slides:slides.value.length>0&&slides.value.every(item=>item.file&&filled(item.caption)&&filled(item.description))}));const specReady=computed(()=>Object.values(sectionComplete.value).every(Boolean)),allAgreed=computed(()=>Object.values(agreements).every(Boolean)),selectedFileContent=computed(()=>generatedFiles.value.find(item=>item.path===selectedFile.value)?.content||"");
const addTag=()=>{const value=tagInput.value.trim().replace(/^#/,"");if(value&&!form.tags.includes(value))form.tags.push(value);tagInput.value="";};function pickSlide(index){slideTarget.value=index;slideInput.value?.click();}function setSlideFile(event){const file=event.target.files?.[0];if(!file)return;const slide=slides.value[slideTarget.value];if(slide.preview)URL.revokeObjectURL(slide.preview);slide.file=file;slide.preview=URL.createObjectURL(file);event.target.value="";}function removeSlide(index){if(slides.value[index].preview)URL.revokeObjectURL(slides.value[index].preview);slides.value.splice(index,1);}
function payload(){return {...form,slides:slides.value.map(item=>({caption:item.caption,description:item.description})),skill_files:generatedFiles.value};}function buildData(){const data=new FormData();data.append("payload_json",JSON.stringify(payload()));slides.value.forEach(item=>item.file&&data.append("slides",item.file));if(form.has_data){if(form.has_train_validation_split){if(files.train)data.append("train_files",files.train);if(files.validation)data.append("validation_files",files.validation);}else if(files.sample)data.append("sample_files",files.sample);}return data;}async function call(path,options={},fallback){const response=await apiFetch(path,options);if(!response.ok)throw await readApiError(response,fallback);return response.status===204?null:response.json();}
async function stageSpec(){if(!specReady.value)return;saving.value=true;error.value="";try{const result=await call("/api/assets/staging",{method:"POST",body:buildData()},"자산 명세서를 임시 저장하지 못했습니다.");form.asset_id=result.asset_id;advance(1);}catch(e){error.value=e.message;}finally{saving.value=false;}}const advance=value=>{maxStep.value=Math.max(maxStep.value,value);step.value=value;window.scrollTo({top:0,behavior:"smooth"});};
async function cloneRepo(){cloning.value=true;repoError.value="";try{const result=await call("/api/assets/repository/clone",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({asset_id:form.asset_id,repo_url:form.repo_url,repo_branch:form.repo_branch||null})},"저장소를 연결하지 못했습니다.");repoTree.value=result.tree||[];}catch(e){repoError.value=e.message;}finally{cloning.value=false;}}
async function planSkills(){planning.value=true;skillError.value="";try{skillPlan.value=await call(`/api/assets/${form.asset_id}/skill-plan`,{method:"POST"},"Skill 후보를 생성하지 못했습니다.");selectedSkills.value=skillPlan.value.selected_skill_slugs||skillPlan.value.candidates.filter(item=>item.recommended).map(item=>item.slug);}catch(e){skillError.value=e.message;}finally{planning.value=false;}}
async function generateSkills(){generating.value=true;skillError.value="";try{const response=await apiFetch(`/api/assets/${form.asset_id}/skills/generate`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({selected_skill_slugs:selectedSkills.value})});if(!response.ok)throw await readApiError(response,"Skill을 생성하지 못했습니다.");const reader=response.body.getReader(),decoder=new TextDecoder();let buffer="";while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);if(event.type==="step_started")generationLabel.value=event.label;if(event.type==="error")throw new Error(event.message);if(event.type==="completed"){generatedFiles.value=event.files||[];selectedFile.value=generatedFiles.value[0]?.path||"";}}if(done)break;}}catch(e){skillError.value=e.message;}finally{generating.value=false;}}
async function submitAsset(){saving.value=true;error.value="";try{await call("/api/assets",{method:"POST",body:buildData()},"자산을 제출하지 못했습니다.");submitted.value=true;await loadMine();}catch(e){error.value=e.message;}finally{saving.value=false;}}async function loadMine(){historyLoading.value=true;try{myAssets.value=await call("/api/assets/mine",{},"등록 기록을 불러오지 못했습니다.");}catch(e){error.value=e.message;}finally{historyLoading.value=false;}}async function viewDocument(asset){try{const response=await apiFetch(`/api/assets/${asset.asset_id}/registration-document`);if(!response.ok)throw await readApiError(response,"등록서를 불러오지 못했습니다.");documentHtml.value=await response.text();}catch(e){error.value=e.message;}}
const statusLabel=value=>({submitted:"제출 완료",approved:"승인",rejected:"반려"}[value]||value),date=value=>String(value||"").slice(0,10);function reset(){slides.value.forEach(item=>item.preview&&URL.revokeObjectURL(item.preview));Object.assign(form,initialForm());Object.assign(files,{sample:null,train:null,validation:null});slides.value=[newSlide()];step.value=0;maxStep.value=0;repoTree.value=[];skillPlan.value=null;generatedFiles.value=[];selectedSkills.value=[];Object.keys(agreements).forEach(key=>agreements[key]=false);submitted.value=false;}
onMounted(loadMine);onBeforeUnmount(()=>slides.value.forEach(item=>item.preview&&URL.revokeObjectURL(item.preview)));
</script>
